create or replace function persist_claim(p_spin_id uuid,p_web_url text default '') returns jsonb language plpgsql security definer set search_path=public as $$declare s spins;begin select * into s from spins where id=p_spin_id for update;if not found then raise exception 'SPIN_NOT_FOUND';end if;if s.status<>'CLAIMED' then update spins set status='CLAIMED',claimed_at=now(),claim_web_url=left(coalesce(p_web_url,''),500),sheet_sync_status='PENDING',sheet_sync_error=null where id=s.id;update prize_units set status='CLAIMED' where id=s.prize_unit_id and status in('AVAILABLE','AWARDED');else update spins set claim_web_url=coalesce(nullif(left(coalesce(p_web_url,''),500),''),claim_web_url) where id=s.id;end if;return jsonb_build_object('ok',true,'spin_id',s.id);end$$;
revoke all on function persist_claim(uuid,text) from public,anon,authenticated;grant execute on function persist_claim(uuid,text) to service_role;
